"use client";
import React, { useState, useEffect } from "react";
import { Search, SendHorizontal, Mail, ChevronRight, MessageSquare, ArrowUpRight, Instagram, ArrowRight } from "lucide-react";
import Link from "next/link";
import { faqData } from "@/data/faq"; 

export default function FAQPage() {
  const [activeId, setActiveId] = useState<string | null>(null);
  const [filter, setFilter] = useState<string>("All");
  const [searchQuery, setSearchQuery] = useState("");
  const [placeholderIndex, setPlaceholderIndex] = useState(0);

  const placeholders = [
    "SEARCH FOR SHIPPING...",
    "HOW DOES COD WORK?",
    "FIND YOUR FIT...",
    "RETURN POLICY DETAILS...",
    "TRACK YOUR DISPATCH..."
  ];

  useEffect(() => {
    const interval = setInterval(() => {
      setPlaceholderIndex((prev) => (prev + 1) % placeholders.length);
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  const filteredFaqs = faqData.filter((item) => {
    const matchesFilter = filter === "All" || item.category === filter;
    const matchesSearch = item.question.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesFilter && matchesSearch;
  });

  const categories = ["All", "Shipping", "Orders", "Returns", "Sizing", "Partnerships"];

  const handleGmailRedirect = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const question = formData.get("question") as string;
    window.location.href = `mailto:support@fashionfriday.in?subject=FAQ Inquiry: ${filter}&body=${encodeURIComponent(question)}`;
  };

  return (
    <div className="bg-background text-foreground min-h-screen pb-20 transition-colors duration-500">
      
      {/* 1. HEADER SECTION - Removed pt-32 to start from top */}
      <section className="pt-10 pb-16 px-6">
        <div className="max-w-7xl mx-auto space-y-12">
          <div className="space-y-4">
            <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full border border-border bg-background-muted text-[10px] font-black uppercase tracking-[0.3em]">
              Knowledge Base / 2026
            </div>
            <h1 className="text-6xl md:text-[7vw] font-black uppercase tracking-[-0.04em] leading-[0.9] italic">
              How can we <br /> <span className="text-foreground-subtle italic">assist?</span>
            </h1>
          </div>

          <div className="space-y-6">
            {/* SEARCH BOX WITH ANIMATED VERTICAL PLACEHOLDER */}
            <div className="relative group w-full max-w-3xl overflow-hidden bg-background-muted rounded-full border border-border focus-within:border-brand transition-all">
              <Search className="absolute left-6 top-1/2 -translate-y-1/2 opacity-30 z-10" size={18} />
              
              <div className="absolute left-14 top-1/2 -translate-y-1/2 pointer-events-none h-full flex items-center">
                {!searchQuery && (
                  <span key={placeholderIndex} className="animate-placeholder text-[11px] font-black uppercase tracking-widest opacity-30">
                    {placeholders[placeholderIndex]}
                  </span>
                )}
              </div>

              <input 
                type="text" 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-transparent py-6 pl-14 pr-6 outline-none uppercase font-black tracking-widest text-[11px] relative z-0"
              />
            </div>
            
            {/* HORIZONTAL SCROLLABLE CATEGORIES */}
            <div className="w-full overflow-x-auto no-scrollbar">
              <div className="flex flex-nowrap gap-3">
                {categories.map((cat) => (
                  <button
                    key={cat}
                    onClick={() => setFilter(cat)}
                    className={`whitespace-nowrap px-8 py-4 rounded-full text-[9px] font-black uppercase tracking-widest border transition-all ${
                      filter === cat ? "bg-brand text-brand-foreground border-brand" : "bg-transparent border-border hover:border-brand"
                    }`}
                  >
                    {cat}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* 2. FAQ LIST */}
      <section className="max-w-4xl mx-auto px-6 mb-32">
        <div className="space-y-4">
          {filteredFaqs.map((faq) => (
            <div 
              key={faq.id}
              className={`rounded-[2.5rem] border transition-all duration-500 ${
                activeId === faq.id ? "bg-background-muted border-brand shadow-sm" : "bg-background border-border"
              }`}
            >
              <button 
                onClick={() => setActiveId(activeId === faq.id ? null : faq.id)}
                className="w-full px-8 py-8 flex items-center justify-between text-left group"
              >
                <h3 className="text-xl font-black uppercase tracking-tight italic group-hover:translate-x-2 transition-transform">
                  {faq.question}
                </h3>
                <div className={`p-2 rounded-full border border-border transition-all ${activeId === faq.id ? "rotate-90 bg-brand text-brand-foreground" : ""}`}>
                  <ChevronRight size={18} />
                </div>
              </button>
              
              {activeId === faq.id && (
                <div className="px-8 pb-10">
                  <div className="border-t border-border pt-6 space-y-4">
                    <p className="text-foreground-muted leading-relaxed font-medium italic">
                      {faq.answer}
                    </p>
                    {faq.href && (
                      <Link href={faq.href} className="inline-flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-brand hover:gap-4 transition-all">
                        View Detailed Policy <ArrowUpRight size={14} />
                      </Link>
                    )}
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </section>

      {/* 3. SUPPORT DISPATCH CENTER (Restored Column Design) */}
      <section className="max-w-7xl mx-auto px-6">
        <div className="bg-background rounded-[4rem] border border-border relative overflow-hidden">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-16 relative z-10">
            
            {/* LEFT: INFO */}
            <div className="lg:col-span-5 space-y-12 p-10 md:p-20">
              <div className="space-y-6">
                <h2 className="text-5xl font-black uppercase tracking-tighter leading-none italic">
                  Drop us <br /> a note.
                </h2>
                <p className="text-foreground-muted leading-relaxed max-w-sm font-medium italic">
                  If the archive node is insufficient, send your question directly to our human support team.
                </p>
              </div>

              <div className="space-y-8">
                <div className="flex items-center gap-6 group cursor-pointer">
                  <div className="p-4 bg-background rounded-full border border-border group-hover:scale-110 transition-transform">
                    <Instagram size={20} />
                  </div>
                  <span className="text-sm font-black uppercase tracking-widest italic border-b border-brand">
                    @fashionfriday.in
                  </span>
                </div>
              </div>
            </div>

            {/* RIGHT: THE FORM (Restored Minimal Box) */}
            <div className="lg:col-span-7 bg-background rounded-[3rem] p-6 md:p-12 border border-border shadow-2xl shadow-black/5 m-4 md:m-8">
              <form onSubmit={handleGmailRedirect} className="space-y-8">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase tracking-widest text-foreground-subtle ml-4">
                    Department: {filter === "All" ? "General Support" : filter}
                  </label>
                  <textarea
                    required
                    name="question"
                    rows={5}
                    placeholder="TELL US ABOUT YOUR VISION OR QUESTION..."
                    className="w-full rounded-[2.5rem] px-8 py-8 bg-background-muted border border-border focus:border-brand outline-none uppercase font-black tracking-widest text-[11px] resize-none transition-all"
                  />
                </div>

                <button className="w-full bg-brand text-brand-foreground py-6 rounded-full font-black uppercase tracking-[0.4em] text-[11px] hover:scale-[0.98] active:scale-[0.96] transition-all flex items-center justify-center gap-4 shadow-xl shadow-brand/20">
                  Send Transmission <SendHorizontal size={16} />
                </button>
              </form>
            </div>
          </div>
        </div>
      </section>

      <footer className="mt-32 text-center">
        <p className="text-[10px] font-black uppercase tracking-[1em] opacity-20 italic">
          Curated in India / 2026
        </p>
      </footer>
    </div>
  );
}